```js
class HttpError extends Error {
  constructor(status) { super(`HTTP ${status}`); this.status = status; }
}

async function getLesson(id) {
  let response;
  try {
    response = await fetch(`/api/lessons/${encodeURIComponent(id)}`, {
      headers: { Accept: "application/json" },
    });
  } catch (error) {
    throw new Error("Network problem. Check your connection.", { cause: error });
  }
  if (!response.ok) throw new HttpError(response.status);   // 404, 500...

  const data = await response.json();                        // may throw SyntaxError.
  if (typeof data?.title !== "string") throw new TypeError("Unexpected lesson format");
  return data;
}
```

| What happened | How it shows up | Message |
|---|---|---|
| no answer (offline, CORS). | fetch rejects (TypeError). | "Check your connection." |
| HTTP error status. | `response.ok === false`. | 404: "Lesson not found". |
| body not JSON. | `response.json()` rejects. | "The server sent an unexpected reply." |
| JSON, wrong shape. | your check fails. | same, and log it. |

